import {SettingsManager} from '@earendil-works/pi-coding-agent';
const s=SettingsManager.inMemory({defaultTools:['read','bash'],terminal:{showImages:true},custom:{value:1}});
s.applyOverrides({defaultTools:['-bash','+write'],custom:{nested:true},terminal:{trueColor:false}});
const merged={settings:s.getSettings(),tools:s.getDefaultTools()};
const undefinedValue=SettingsManager.inMemory({custom:undefined,retry:{enabled:false}}).getSettings();
const clone={hasUndefined:Object.hasOwn(undefinedValue,'custom'),retry:undefinedValue.retry};
const errors=[];
for(const [key,value] of [['reserveTokens',-1],['keepRecentTokens',1.5],['reserveTokens','oops']]){const settings=SettingsManager.inMemory({compaction:{[key]:value}});
try{settings.getCompactionSettings({provider:'p',id:'m'})}catch(e){errors.push({name:e.name,message:e.message})}}const analytics=SettingsManager.inMemory();
analytics.setEnableAnalytics(false);
const noTracking=analytics.getTrackingId()===undefined;
analytics.setEnableAnalytics(true);
const tracking=analytics.getTrackingId();
const valid=id=>typeof id==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(id);
analytics.setEnableAnalytics(true);
const device=analytics.getOrCreateDeviceId();
const identity={noTracking,trackingValid:valid(tracking),trackingStable:tracking===analytics.getTrackingId(),deviceValid:valid(device),deviceStable:device===analytics.getOrCreateDeviceId(),different:device!==tracking};
const globalOnly=SettingsManager.fromStorage({withLock(scope,fn){fn(scope==='global'?JSON.stringify({deviceId:'global-device'}):JSON.stringify({deviceId:'project-device'}))}});
identity.globalDevice=globalOnly.getOrCreateDeviceId();
const paths=[];
for(const value of ['relative/dir','/unchanged/path','~/directory/../target','~','']){const settings=SettingsManager.inMemory({shellPath:value,sessionDir:value});
const shell=settings.getShellPath(),session=settings.getSessionDir();
paths.push({same:shell===session,relative:value==='~'||value.startsWith('~/')?String(shell).split(String.fromCharCode(92)).join('/').endsWith(value==='~'?'': '/target'):shell===value,expanded:value.startsWith('~')?!String(shell).startsWith('~'):true})}await analytics.flush();
console.log(JSON.stringify({merged,clone,errors,identity,paths}));
